#include <stdio.h>
int main(void) {
    int attempts[3] = {1111, 1234, 0};
    int count = 0, success = 0;
    do {
        if (attempts[count] == 1234) {
            success = 1;
            break;
        }
        count++;
    } while (count < 3);
    printf("Success: %d, Count: %d\n", success, count);
    return 0;
}

#include <stdio.h>
int main(void) {
    int packets[] = {10, 20, 30, 255, 40};
    int i = 0, sum = 0;
    while (packets[i] != 255) {
        sum += packets[i];
        i++;
    }
    printf("Sum=%d Packets=%d\n", sum, i);
    return 0;
}
